import { EXHIBITS, PUZZLES, SOURCES } from './exhibit-content.js';
import { formatElapsed } from './session.js';
import { HISTORY } from './exhibit-history.js';
import { EQ_ANSWERS } from './eq-answers.js';
const escape=text=>String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const prose=text=>String(text).split(/\n\n+/).map(p=>'<p>'+escape(p)+'</p>').join('');
export class EvidenceProgress {
 constructor(){this.reset();}
 reset(){this.inspected=new Set();this.steps={};this.hints={};this.attempts=0;this.incorrectMcq=0;}
 inspect(id){if(EXHIBITS.some(e=>e.id===id))this.inspected.add(id);}
 count(room){return EXHIBITS.filter(e=>e.room===room&&this.inspected.has(e.id)).length;}
 ready(room){const ids=PUZZLES[room]?.requiredIds??EXHIBITS.filter(e=>e.room===room).map(e=>e.id);return ids.every(id=>this.inspected.has(id));}
 answer(room,id){if(!this.ready(room))return false;const index=this.steps[room]??0,step=PUZZLES[room]?.steps?.[index];if(!step||!step.options.some(o=>o.id===id))return false;this.attempts++;if(id!==step.answer){this.incorrectMcq++;return false;}this.steps[room]=index+1;return true;}
 enterCode(room,code){if(!this.ready(room)||!PUZZLES[room]?.code||this.complete(room))return false;this.attempts++;if(String(code).toUpperCase()!==PUZZLES[room].code)return false;this.steps[room]=1;return true;}
 complete(room){return this.steps[room]===(PUZZLES[room]?.code?1:PUZZLES[room]?.steps.length);}
}
export function createExhibitUI({session,rooms,currentRoom,beforeOpen,onProgress,toast,sound}){
 const $=id=>document.getElementById(id),progress=new EvidenceProgress(),dialog=$('exhibitDialog'),body=$('exhibitBody');let activeRoom=null,feedback='',selected='',lastRoomId='',finalResults=null;
 function sources(ids){return ids.map(id=>SOURCES.find(s=>s.id===id)).filter(Boolean).map(s=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)} ↗</a><span>${escape(s.author)} · ${escape(s.date)} · ${escape(s.type)}</span></li>`).join('');}
 function open(){beforeOpen();if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
 function close(){dialog.close();window.speechSynthesis?.cancel();$('world').focus();}
 function heading(kicker,title){body.innerHTML=`<p class="eyebrow">${escape(kicker)}</p><h2 id="exhibitTitle">${escape(title)}</h2>`;}
 function footer(){body.insertAdjacentHTML('beforeend','<button class="text-action" id="backCollection">← Gallery collection</button>');$('backCollection').onclick=()=>collection(activeRoom);}
 function remaining(room){return EXHIBITS.filter(e=>e.room===room&&!progress.inspected.has(e.id));}
 function exhibit(id){
  window.speechSynthesis?.cancel();
  const item=EXHIBITS.find(e=>e.id===id);
  if(!item||currentRoom()?.id!==item.room||!session.canEnter(item.room))return;
  activeRoom=item.room;progress.inspect(id);sound('click');
  const history=HISTORY[id],next=remaining(item.room)[0],count=EXHIBITS.filter(e=>e.room===item.room).length;
  heading(`${rooms.find(r=>r.id===item.room).short} · ${item.year}`,item.title);
  body.insertAdjacentHTML('beforeend',`<div class="source-tag">${escape(item.year)}${item.code?' · MUSEUM FILE LABEL '+escape(item.code):''}</div><p class="artifact-copy">${escape(item.description)}</p><section class="history-panel" aria-label="Historical background"><h3>What happened in history?</h3>${prose(history.event)}<h3>Why it matters</h3>${prose(history.meaning)}</section>${item.caseNote?'<aside class="case-annotation"><h3>Investigator’s annotation</h3><p>'+escape(item.caseNote)+'</p></aside>':''}${session.mode==='explore'?`<div class="clue-note"><span>CURATOR’S CLUE · WHAT TO EXPLORE NEXT</span><p>${escape(item.clue)}</p></div>`:''}<div class="exhibit-toolbar"><button id="readAloud">Read aloud</button><span>Evidence collected · ${progress.count(item.room)} / ${count}</span></div>${item.media?`<p class="archive-audio"><a target="_blank" rel="noopener noreferrer" href="${escape(SOURCES.find(s=>s.id===item.media)?.url)}">${item.media==='coolidge-audio'?'Explore original archival recordings':'Listen to the original archival recording'} ↗</a><small>Library of Congress; opens in a new tab. Browser read-aloud is a modern synthesized voice.</small></p>`:''}<details class="citations" open><summary>Historical sources</summary><ul>${sources(item.sources)}</ul></details><button class="primary" id="nextStop">${next?'Inspect next: '+escape(next.title):'Open this room’s lock or evidence desk'} <span>→</span></button>`);
  $('readAloud').onclick=()=>{if(!window.speechSynthesis){toast('Read-aloud is unavailable in this browser. The full text is above.');return;}window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(item.title+'. '+item.description+'. What happened in history? '+history.event+'. Why it matters. '+history.meaning+(item.caseNote?'. Investigator’s annotation. '+item.caseNote:'')+(session.mode==='explore'?'. Curator’s clue. '+item.clue:''));utterance.rate=.92;window.speechSynthesis.speak(utterance);};
  $('nextStop').onclick=()=>next?exhibit(next.id):puzzle(item.room);
  footer();open();update();
 }
 function collection(room=currentRoom()?.id){
  if(!room)return;if(room==='reference'){reference();return;}
  if(currentRoom()?.id!==room||!session.canEnter(room))return;
  activeRoom=room;
  const list=EXHIBITS.filter(e=>e.room===room),next=remaining(room)[0];
  heading('GALLERY FIELD NOTES',rooms.find(r=>r.id===room).name);
  body.insertAdjacentHTML('beforeend',`<div class="route-guide"><b>HOW TO COMPLETE THIS GALLERY</b><p>Inspect the ${list.length} artifacts below. ${session.mode==='explore'?'Follow their curator’s clues or choose from the list.':'Use their history and labels to identify the evidence you need.'}</p><p>${room==='campaign'?'Enter the 1924 plan’s four-digit archive stamp at Gallery 2’s door or this desk.':room==='diplomacy'?'Find three correct files and combine their labels at Gallery 4’s door.':room==='teapot'?'Use the evidence-box arithmetic at Gallery 5’s door.':'Answer three historical questions at the evidence desk.'}</p><p class="current-step">${next?'UNINSPECTED: '+escape(next.title):progress.complete(room)?'COMPLETE: Gallery solved.':'The desk is ready when you have the required evidence.'}</p></div><div class="collection-list">${list.map((e,i)=>`<button data-exhibit="${e.id}"><b>${String(i+1).padStart(2,'0')}</b><span>${escape(e.title)}<small>${escape(e.year)} · ${progress.inspected.has(e.id)?'Inspected':'Inspect exhibit'}</small></span><em>${progress.inspected.has(e.id)?'✓':'↗'}</em></button>`).join('')}</div><button id="toPuzzle" class="primary">${PUZZLES[room].code?'Open the lock':room==='study'?'Open the final scroll':'Open the evidence desk'} <span>→</span></button>`);
  body.querySelectorAll('[data-exhibit]').forEach(b=>b.onclick=()=>exhibit(b.dataset.exhibit));
  $('toPuzzle').onclick=()=>puzzle(room);open();
 }
 function puzzle(room){if((currentRoom()?.id!==room&&!(PUZZLES[room]?.code&&currentRoom()===null))||!session.canEnter(room))return;activeRoom=room;feedback='';selected='';renderPuzzle();open();}
 function renderPuzzle(){const room=activeRoom,p=PUZZLES[room];heading(room==='study'?'FINAL GALLERY · TEAM B':'CONNECT THE EVIDENCE',p.title);
 if(p.code){const count=EXHIBITS.filter(e=>e.room===room).length,word=/[A-Z]/.test(p.code),nextRoom=rooms[rooms.findIndex(r=>r.id===room)+1];body.insertAdjacentHTML('beforeend',`<p class="artifact-copy">${escape(p.intro)}</p><div class="clue-note"><span>THE DOOR’S QUESTION</span><p>${escape(p.prompt)}</p></div>${room==='campaign'?'<p class="dialog-sub">The archive stamps are game codes, not historical dates.</p>':''}<label for="lockInput">${word?'Five-letter file code':room==='teapot'?'Six-digit evidence-box total':'Four-digit archive stamp'}</label><div class="lock-row"><input id="lockInput" inputmode="${word?'text':'numeric'}" maxlength="${p.code.length}" autocomplete="off" aria-describedby="lockFeedback" placeholder="${word?'_____':'0'.repeat(p.code.length)}"><button id="submitCode" class="primary">Unlock →</button></div><p id="lockFeedback" role="status" class="puzzle-feedback">${escape(feedback)}</p><div class="hint-row"><button id="hintBtn">Hint ${Math.min((progress.hints[room]??0)+1,3)} / 3</button><span>${progress.count(room)} / ${count} artifacts inspected</span></div><p class="hint-text">${progress.hints[room]?escape(p.hints[progress.hints[room]-1]):''}</p>`);$('hintBtn').onclick=()=>{progress.hints[room]=Math.min((progress.hints[room]??0)+1,3);renderPuzzle();};const submit=()=>{const code=$('lockInput').value.trim();if(progress.complete(room)){feedback='Already unlocked. Continue to Gallery '+nextRoom.number+'.';renderPuzzle();return;}if(!progress.ready(room)){sound('locked');feedback=room==='diplomacy'?'Inspect the three files that answer the policy clues. The other three are optional.':'Inspect all four artifacts first, then return to the lock.';renderPuzzle();return;}if(!progress.enterCode(room,code)){sound('locked');feedback='That code does not fit the evidence. Compare the historical information and file labels, or use a hint.';renderPuzzle();return;}if(session.mode==='escape'){session.completeGallery(room);onProgress();}sound('success');feedback='Correct. Gallery '+nextRoom.number+' is unlocked. Return to the Grand Hall and open its door.';renderPuzzle();};$('submitCode').onclick=submit;$('lockInput').onkeydown=e=>{if(e.key==='Enter')submit();};footer();return;}
 if(!progress.ready(room)){const missing=remaining(room);body.insertAdjacentHTML('beforeend',`<p class="artifact-copy">${escape(p.prompt)}</p><div class="clue-note"><span>${progress.count(room)} OF 4 EXHIBITS INSPECTED</span><p>Inspect the remaining artifacts, then return here for three questions. The next gallery unlocks after the third correct answer.</p></div><h3>Still to inspect</h3><div class="collection-list">${missing.map(e=>`<button data-exhibit="${e.id}">${escape(e.title)} <span>↗</span></button>`).join('')}</div>`);body.querySelectorAll('[data-exhibit]').forEach(b=>b.onclick=()=>exhibit(b.dataset.exhibit));footer();return;}
 if(progress.complete(room)){body.insertAdjacentHTML('beforeend',`<p class="artifact-copy">This gallery’s evidence is complete.</p><div class="clue-note"><span>${session.mode==='escape'?'GALLERY COMPLETE':'FREE EXPLORATION'}</span><p>${session.mode==='escape'?(room==='study'?'All five galleries are solved. Open the Reference Room door to stop the clock and see your results.':'The next gallery is unlocked. Return through the door into the Grand Hall.'):'All galleries remain open. Explore or try another evidence desk.'}</p></div>`);if(room==='study'&&session.finishedAt!==null){body.insertAdjacentHTML('beforeend','<button class="primary" id="resultsAgain">View escape result →</button>');$('resultsAgain').onclick=win;}footer();return;}
 const index=progress.steps[room]??0,step=p.steps[index],used=progress.hints[room]??0;
 body.insertAdjacentHTML('beforeend',`<p class="dialog-sub">${escape(p.prompt)}</p><div class="puzzle-progress">${p.steps.map((_,i)=>`<i class="${i<=index?'filled':''}"></i>`).join('')}<span>Evidence ${index+1} / ${p.steps.length}</span></div><h3 class="question">${escape(step.question)}</h3><div class="answer-options">${step.options.map((o,i)=>`<button data-answer="${escape(o.id)}" ${selected===o.id?'class="selected"':''}><b>${String.fromCharCode(65+i)}</b><span>${escape(o.text)}</span></button>`).join('')}</div><div id="puzzleFeedback" class="puzzle-feedback" role="status">${escape(feedback)}</div><button id="submitEvidence" class="primary" ${selected?'':'disabled'}>Submit evidence <span>→</span></button><div class="hint-row"><button id="hintBtn">Hint ${Math.min(used+1,p.hints.length)} / ${p.hints.length}</button><span>No time penalty · hints recorded</span></div><p class="hint-text">${used?escape(p.hints[Math.min(used,p.hints.length)-1]):''}</p>`);
 body.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{selected=b.dataset.answer;feedback='';renderPuzzle();});$('hintBtn').onclick=()=>{progress.hints[room]=Math.min(used+1,p.hints.length);renderPuzzle();};
 $('submitEvidence').onclick=()=>{if(!progress.answer(room,selected)){sound('locked');feedback='That conclusion does not fit the evidence. Revisit the clues or use a hint, then try again.';renderPuzzle();return;}if(progress.complete(room)&&session.mode==='escape'){session.completeGallery(room);onProgress();}sound('success');heading('EVIDENCE VERIFIED',index===p.steps.length-1?'The connection is clear.':'You found the connection.');body.insertAdjacentHTML('beforeend',`<p class="artifact-copy">${escape(step.explanation)}</p><ul class="answer-sources">${sources(step.sourceIds??[])}</ul><button id="nextEvidence" class="primary">${progress.complete(room)?(room==='study'?'Continue to the bibliography room':session.mode==='escape'?'Unlock the next gallery':'Complete this gallery'):'Continue the investigation'} <span>→</span></button>`);$('nextEvidence').onclick=()=>{feedback='';selected='';if(progress.complete(room)){if(session.mode==='escape'){if(room==='study'){toast('Bibliography room unlocked · Open its door to finish.');renderPuzzle();return;}toast('Gallery '+session.unlockedCount+' unlocked');}renderPuzzle();}else renderPuzzle();};};footer();}
 function reference(topic){
  if(topic&&EQ_ANSWERS[topic]){const eq=EQ_ANSWERS[topic];heading('REFERENCE ROOM · '+topic.toUpperCase(),eq.label);body.insertAdjacentHTML('beforeend',`<h3>${escape(eq.question)}</h3>${eq.paragraphs.map(t=>'<p class="artifact-copy">'+escape(t)+'</p>').join('')}<h3>Evidence behind this interpretation</h3><ul class="bibliography">${sources(eq.sourceIds)}</ul><button id="otherEq" class="primary">Open the other EQ library →</button><button id="fullRefs" class="text-action">View complete bibliography</button>`);$('otherEq').onclick=()=>reference(topic==='a1'?'d1':'a1');$('fullRefs').onclick=()=>reference();open();return;}
  heading('THE REFERENCE ROOM','Sources behind the story.');body.insertAdjacentHTML('beforeend',`<p class="artifact-copy">The two bookshelves give the complete answers to essential questions A1 and D1. The museum’s display objects and document illustrations are reconstructions. File labels organize the collection; the evidence-box balance is an invented accounting exercise, while the historical panels describe the documented events.</p><div class="collection-list"><button id="openA1">Library A1 · Civic ideals and the common good →</button><button id="openD1">Library D1 · Cause, change, and policy →</button></div><h3>Learning objectives</h3><ul class="learning-list"><li>Use specific evidence and identify a source’s date and origin.</li><li>Explain connections between World War I, 1920s policy, and later vulnerabilities.</li><li>Learn independently through artifacts and sources.</li></ul><h3>Bibliography</h3><ul class="bibliography">${sources(SOURCES.map(s=>s.id))}</ul><p class="dialog-sub">Museum props are reconstructions. Browser read-aloud is synthetic; linked Library of Congress speeches are original recordings.</p>`);$('openA1').onclick=()=>reference('a1');$('openD1').onclick=()=>reference('d1');open();}
 function win(){heading('INVESTIGATION COMPLETE','Congratulations, historian.');const hints=finalResults?.hints??Object.values(progress.hints).reduce((a,b)=>a+b,0);body.insertAdjacentHTML('beforeend',`<p class="artifact-copy">You escaped the Museum of Normalcy by connecting its evidence.</p><div class="result-time"><span>YOUR ESCAPE TIME</span><strong>${formatElapsed(session.elapsedMs)}</strong></div><div class="result-stats"><span><b>${finalResults?.incorrectMcq??progress.incorrectMcq}</b> Incorrect MCQ answers</span><span><b>${hints}</b> Hints used</span></div><p class="dialog-sub">Go to the Reference Room and click both library bookshelves to read the complete A1 and D1 essential-question answers. Time includes reading and menus.</p><button class="primary" id="finishExplore">Continue exploring <span>→</span></button>`);$('finishExplore').onclick=close;open();sound('success');}
 function interact(data){if(!data)return;if(data.type==='exhibit')exhibit(data.id);else if(data.type==='puzzle')puzzle(data.room);else reference(data.topic);}
 function update(){const room=currentRoom();$('collectionBtn').hidden=!room;$('collectionBtn').textContent=room?.id==='reference'?'EQ libraries & bibliography ↗':`Room exhibits · ${room?progress.count(room.id):0} / ${room?EXHIBITS.filter(e=>e.room===room.id).length:4}`;$('collectionBtn').onclick=()=>collection();if(room?.id!==lastRoomId){lastRoomId=room?.id;}}
 dialog.addEventListener('close',()=>{window.speechSynthesis?.cancel();$('world').focus();});$('closeExhibit').onclick=close;
 return {interact,update,progress,finishAtReference(){if(session.finish()){finalResults={incorrectMcq:progress.incorrectMcq,hints:Object.values(progress.hints).reduce((a,b)=>a+b,0)};onProgress();win();}},reset(){progress.reset();finalResults=null;dialog.close();window.speechSynthesis?.cancel();},isOpen:()=>dialog.open};
}
